#!/usr/bin/env node
"use strict";
// Generated by the System2 compiler. Do not edit by hand.
// Invalid input and internal errors fail closed.

const MAX_INPUT_BYTES = 1048576;
const MAX_MATCH_LEN = 16384;
const WATCHDOG_MS = 2000;
const HOOK_EVENT = "PreToolUse";
const CANARY_SENTINEL = "system2-hook-canary";
const CANARY_BASE_REASON = "system2-canary-blocked";
const DEFAULT_ACTIVE_ROLE = "executor";

// Ported from _enforcement.build_sensitive_path_patterns(): segment/basename-anchored.
const SENSITIVE_REGEXES = [
  [new RegExp("(^|/)\\.env$", ""), "Environment file (.env)"],
  [new RegExp("(^|/)\\.env\\.[A-Za-z0-9_-]+$", ""), "Environment file (.env.*)"],
  [new RegExp("(^|/)\\.ssh(/|$)", ""), "SSH directory (.ssh/)"],
  [new RegExp("(^|/)\\.git(/|$)", ""), "Git directory (.git/)"],
  [new RegExp("(^|/)\\.aws(/|$)", ""), "AWS credentials directory (.aws/)"],
  [new RegExp("(^|/)\\.gnupg(/|$)", ""), "GPG directory (.gnupg/)"],
  [new RegExp("credentials", "i"), "File containing 'credentials'"],
  [new RegExp("secrets", "i"), "File containing 'secrets'"],
  [new RegExp("\\.pem$", "i"), "PEM certificate/key file (*.pem)"],
  [new RegExp("\\.key$", "i"), "Key file (*.key)"],
  [new RegExp("(^|/)id_rsa$", ""), "RSA private key (id_rsa)"],
  [new RegExp("(^|/)id_ed25519$", ""), "Ed25519 private key (id_ed25519)"],
  [new RegExp("(^|/)id_ecdsa$", ""), "ECDSA private key (id_ecdsa)"],
  [new RegExp("(^|/)\\.netrc$", ""), "Netrc credentials file (.netrc)"],
  [new RegExp("(^|/)\\.npmrc$", ""), "NPM config file (.npmrc) - may contain tokens"],
  [new RegExp("(^|/)\\.pypirc$", ""), "PyPI config file (.pypirc) - may contain tokens"],
];

// Path-normalizing, fail-closed lease matcher.
// Per-role write scopes; absent or empty scopes deny writes.
const ROLE_WRITE_SCOPES = new Map([
  ["repo-governor", "^(CLAUDE\\.md|AGENTS\\.md|\\.claude/settings\\.json|spec/INDEX\\.md)$"],
  ["spec-coordinator", "^spec/context\\.md$"],
  ["requirements-engineer", "^spec/requirements\\.md$"],
  ["design-architect", "(?:^spec/design\\.md$)|(?:^spec/interfaces\\.json$)|(?:^spec/module-boundaries\\.json$)"],
  ["task-planner", "^spec/tasks\\.md$"],
  ["executor", "^(?!third_party/|vendor/|node_modules/|dist/|build/|out/|\\.git/).*(^spec/.*\\.md$|^docs/.*\\.md$|^README\\.md$|^CHANGELOG\\.md$|(^|/)(BUILD|WORKSPACE)(\\.bazel)?$|.*\\.(py|go|java|kt|kts|ts|tsx|js|jsx|rs|c|cc|cpp|h|hpp|cs|proto|sql|yaml|yml|json|toml|sh|bazel|bzl)$)"],
  ["test-engineer", "^(?!third_party/|vendor/|node_modules/|dist/|build/|out/|\\.git/).*(^spec/.*\\.md$|^docs/.*\\.md$|.*(/__tests__/|/tests?/).*\\.(py|go|java|kt|kts|ts|tsx|js|jsx|rs|c|cc|cpp|cs)$|.*(_test\\.go|\\.test\\.(ts|tsx|js|jsx)|\\.spec\\.(ts|tsx|js|jsx)|test_.*\\.py|.*_test\\.py)$|(^|/)(BUILD|WORKSPACE)(\\.bazel)?$|.*\\.(yaml|yml|json|toml)$)"],
  ["security-sentinel", "^spec/security\\.md$"],
  ["eval-engineer", "^(spec/evals\\.md|evals/.*\\.(md|py|yaml|yml|json|toml))$"],
  ["docs-release", "^(README\\.md|CHANGELOG\\.md|MIGRATIONS\\.md|docs/.*\\.md|spec/.*\\.md)$"],
  ["code-reviewer", ""],
  ["postmortem-scribe", "^postmortems/.*\\.md$"],
  ["mcp-toolsmith", "^(spec/mcp\\.md|mcp/.*\\.(md|py|ts|js|json|yaml|yml))$"],
]);
const WRITEABLE_ROLES = new Set(["code-reviewer", "design-architect", "docs-release", "eval-engineer", "executor", "mcp-toolsmith", "postmortem-scribe", "repo-governor", "requirements-engineer", "security-sentinel", "spec-coordinator", "task-planner", "test-engineer"]);

// Normalize project-relative paths and return null on any escape.
function normalizeProjectPath(p) {
  if (typeof p !== "string" || p.length === 0) return null;
  if (p === "~" || p.startsWith("~/")) return null; // home dir: outside project
  const slashed = p.replace(/\\/g, "/");
  if (slashed.startsWith("/")) return null; // absolute: cannot confirm in-project -> block
  const segs = [];
  for (const part of slashed.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === "..") {
      if (segs.length === 0) return null; // escapes the project root -> block
      segs.pop();
      continue;
    }
    segs.push(part);
  }
  return segs.join("/");
}

// Return the first lease violation; invalid scopes fail closed.
function leaseViolation(activeRole, paths) {
  if (!paths || paths.length === 0) return undefined;
  const scope = ROLE_WRITE_SCOPES.get(activeRole);
  if (!WRITEABLE_ROLES.has(activeRole) || !scope) return paths[0];
  let re;
  try {
    re = new RegExp("^(?:" + scope + ")");
  } catch {
    return paths[0]; // an uncompilable scope fails closed, not open
  }
  for (const p of paths) {
    const norm = normalizeProjectPath(p);
    if (norm === null || !re.test(norm)) return p; // escape or off-scope -> block
  }
  return undefined;
}

// --- fail-closed decision plumbing ------------------------------------
function denyJson(reason) {
  return JSON.stringify({ hookSpecificOutput: { hookEventName: HOOK_EVENT, permissionDecision: "deny", permissionDecisionReason: reason } });
}
function block(reason) {
  try { process.stdout.write(denyJson(reason)); } catch (e) {}
  process.exit(0);
}
function allow() { process.exit(0); }
// Emit a denial before the non-zero fallback exit.
function failClosed(reason) {
  try { process.stdout.write(denyJson(reason)); } catch (e) {}
  try { process.stderr.write("system2-hook-error: " + String(reason) + "\n"); } catch (e) {}
  process.exit(2);
}

function activeRole() {
  const r = process.env.SYSTEM2_ACTIVE_ROLE;
  return (typeof r === "string" && r.length > 0) ? r : DEFAULT_ACTIVE_ROLE;
}

// Parse the nonce from a canary command (touch .system2/canary-<nonce>).
function parseNonce(text) {
  const m = /canary-([A-Za-z0-9][A-Za-z0-9._-]*)/.exec(String(text));
  return m ? m[1] : null;
}
// Match canary target paths, not sentinel text in file content.
function canaryReason(paths) {
  for (const p of paths) {
    if (/(^|\/)\.system2\/canary-[A-Za-z0-9][A-Za-z0-9._-]*$/.test(p)) {
      return CANARY_BASE_REASON + ":" + parseNonce(p);
    }
  }
  return undefined;
}

function sensitiveHit(text) {
  if (!text) return undefined;
  for (const [re, description] of SENSITIVE_REGEXES) {
    if (re.test(text)) return description;
  }
  return undefined;
}


const PATH_KEYS = [
  "path", "file_path", "filepath", "filename", "file", "target_file",
  "from", "to", "source", "destination", "old_path", "new_path",
];

function pathsOf(event) {
  if (!event || typeof event !== "object" || Array.isArray(event)) return null;
  const input = (event.tool_input || event.toolInput || event.input || event.arguments) || {};
  if (!input || typeof input !== "object" || Array.isArray(input)) return null;
  const out = [];
  for (const key of PATH_KEYS) {
    const v = input[key];
    if (typeof v === "string" && v.length > 0) out.push(v);
  }
  // Extract patch paths only when no explicit write path is present.
  const patch = (typeof input.patch === "string") ? input.patch
              : (typeof input.input === "string") ? input.input
              : (out.length === 0 && typeof input.content === "string") ? input.content : "";
  if (patch) {
    const re = /^\s*(?:\*\*\* (?:Add|Update|Delete) File: |\+\+\+ (?:b\/)?|--- (?:a\/)?)(.+?)\s*$/gm;
    let m; let guard = 0;
    while ((m = re.exec(patch)) !== null) {
      if (guard >= 512) return { paths: out, overflow: true };
      guard++;
      const p = m[1].trim();
      if (p && p !== "/dev/null") out.push(p);
    }
  }
  if (out.length === 0) return null;
  return { paths: out, overflow: false };
}

function decide(event, raw) {
  const extracted = pathsOf(event);
  if (extracted === null) return "enforce-lease: uninspectable routed edit event (candidate fail closed)";
  if (extracted.overflow) return "enforce-lease: patch path extraction limit exceeded (candidate fail closed)";
  const paths = extracted.paths;
  // This candidate hook carries its own canary sentinel (defense-in-depth).
  const cr = canaryReason(paths);
  if (cr) return cr;
  for (const p of paths) {
    if (p.length > MAX_MATCH_LEN) return "protect-sensitive: path exceeds safe match length (fail closed)";
    const sh = sensitiveHit(p);
    if (sh) return "protect-sensitive: " + sh;
  }
  const off = leaseViolation(activeRole(), paths);
  if (off) return "enforce-lease: " + off + " is outside the write scope for role " + activeRole();
  return undefined;
}

function run(raw) {
  if (raw.length > MAX_INPUT_BYTES) { failClosed("stdin exceeds maximum size"); return; }
  let event;
  try { event = JSON.parse(raw); }
  catch (e) { failClosed("malformed JSON on stdin"); return; }
  try {
    const reason = decide(event, raw);
    if (reason) block(reason); else allow();
  } catch (e) {
    failClosed("hook exception: " + (e && e.message ? e.message : String(e)));
  }
}

// Block when the watchdog expires.
let watchdog = setTimeout(() => { failClosed("watchdog timeout before decision"); }, WATCHDOG_MS);
let buf = "";
let over = false;
process.stdin.setEncoding("utf8");
process.stdin.on("data", (c) => {
  if (over) return;
  buf += c;
  if (buf.length > MAX_INPUT_BYTES) {
    over = true;
    clearTimeout(watchdog);
    failClosed("stdin exceeds maximum size");
  }
});
process.stdin.on("end", () => { clearTimeout(watchdog); run(buf); });
process.stdin.on("error", () => { clearTimeout(watchdog); failClosed("stdin read error"); });
